function checkoutV1(items){let t=0;for(const i of items){let line=i.price*i.qty;if(i.qty>=10)line=line*0.9;t+=line;}return Math.round(t);}
function checkoutV2(items){return Math.round(items.reduce((t,i)=>t+i.price*i.qty*(i.qty>=10?0.9:1),0));}
const items=[{price:100,qty:12},{price:50,qty:1}];
const a=checkoutV1(items),b=checkoutV2(items);
console.log(a===b&&a===1130?'PASS':'FAIL '+a+' '+b);
